#!/usr/bin/env bash
set -euo pipefail
cd "$(dirname "$0")/.."
[[ -f .env ]] || { echo 'Run bash scripts/init-dev-env.sh first.' >&2; exit 1; }
task_database_override=${SQL_DATABASE:-}
# .env is local trusted configuration generated by init-dev-env.sh. Never source an untrusted file.
set -a
source .env
set +a
export Jwt__SigningKey="$JWT_SIGNING_KEY"
export Auth__AdminPassword="$ADMIN_PASSWORD"
export Auth__StaffPassword="$STAFF_PASSWORD"
export Payments__WebhookSecret="$PAYMENT_WEBHOOK_SECRET"
export Gateway__SimulationMode="${Gateway__SimulationMode:-${GATEWAY_SIMULATION_MODE:-}}"
export ConnectionStrings__DefaultConnection="${ConnectionStrings__DefaultConnection:-Server=localhost,1433;Database=${task_database_override:-${SQL_DATABASE:-OrderPayment}};User Id=sa;Password=$MSSQL_SA_PASSWORD;Encrypt=True;TrustServerCertificate=True}"
export Database__MigrateOnStartup="${Database__MigrateOnStartup:-true}"
export ASPNETCORE_ENVIRONMENT=Development
export ASPNETCORE_URLS=http://localhost:8080
exec dotnet run --project src/OrderPayment.Api "$@"
